    "這是一個「世界會自己運作」的歷史模擬遊戲。": "Đây là trò chơi mô phỏng lịch sử, nơi thế giới tự vận hành.",
    "你選一個起點，人口、經濟、政治、科技、外交與戰爭會由模擬器一步一步推進；你可以只是觀察，偶爾介入，或改變世界的根本規則。": "Bạn chọn một điểm khởi đầu, trình mô phỏng sẽ đưa dân số, kinh tế, chính trị, công nghệ, ngoại giao và chiến tranh tiến lên từng bước. Bạn có thể chỉ quan sát, thỉnh thoảng can thiệp, hoặc thay đổi luật lệ nền tảng của thế giới.",
