    "《人類的黎明》：從西元前 10,000 年的狩獵採集開始": "\"Bình minh nhân loại\": bắt đầu từ săn bắt hái lượm năm 10.000 TCN",
    "《人類的黎明》：每條世界線都不一樣（種子已記錄在「系統」頁的開發者資訊）": "\"Bình minh nhân loại\": mỗi dòng thời gian đều khác nhau (hạt giống được ghi trong thông tin nhà phát triển ở trang Hệ thống)",
    "「{0}」世界上還沒有人完成，且{1}具備前置科技": "Chưa ai trên thế giới hoàn thành \"{0}\", và {1} đã đủ điều kiện",
    "「{0}」在這條世界線沒有發生": "\"{0}\" đã không xảy ra trong dòng thời gian này",
    "「{0}」已有國家掌握，且{1}具備前置科技": "\"{0}\" đã được một nước biết đến, và {1} đã đủ điều kiện",
    "「{0}」是怎麼來的？": "\"{0}\" đến từ đâu?",
    "「{0}」的前置技術與地理條件都具備": "Điều kiện và địa lý cho \"{0}\" đã đầy đủ",
    "「{0}」脫離{1}，成為獨立政治實體。": "\"{0}\" tách khỏi {1} và trở thành chính thể độc lập.",
    "「{0}」解散": "\"{0}\" giải thể",
    "「備份存檔」會把這個世界存成一個檔案放到你的裝置上；換手機、清除瀏覽器資料之前，或想把世界分享給朋友時使用。": "\"Sao lưu bản lưu\" lưu thế giới này thành tệp trên thiết bị của bạn; hãy dùng trước khi đổi điện thoại, xóa dữ liệu trình duyệt, hoặc khi muốn chia sẻ thế giới với bạn bè.",
    "「如果」平行世界：{0}。": "Thế giới song song \"Nếu như?\": {0}.",
    "「沒有你的世界」：不重播你的介入重跑一次，比較哪個世界先毀滅": "\"Thế giới không có bạn\": chạy lại mà không có can thiệp của bạn, xem thế giới nào kết thúc trước",
    "「沒有國家」與「允許戰爭」互相衝突：沒有國家時不存在國家間戰爭。": "\"Không có nhà nước\" mâu thuẫn với \"Cho phép chiến tranh\": không có nhà nước thì không có chiến tranh giữa các nước.",
    "「沒有貨幣」與「存在資本主義」互相衝突：資本主義需要以貨幣計價的資本市場。": "\"Không có tiền\" mâu thuẫn với \"Có chủ nghĩa tư bản\": chủ nghĩa tư bản cần thị trường vốn định giá bằng tiền.",
    "「直接死亡」是發生當下的死亡；「之後的死亡」是它留下的長期影響（臨界點的額外升溫、核子寒冬）在之後每年多造成的死亡，依公式拆分。": "\"Tử vong trực tiếp\" là số chết lúc đó; \"tử vong về sau\" là số chết thêm ở những năm sau do tác động kéo dài (nóng lên thêm từ điểm bùng phát, mùa đông hạt nhân), tách ra bằng công thức.",
    "「讀取備份」選那個檔案就能回到這個世界。": "Chọn tệp đó trong \"Tải bản sao lưu\" để quay lại thế giới này.",
    "」可以追查），每場災難都是事件，可以用「如果？": "\" để truy vết), và mỗi thảm họa là một sự kiện mà \"Nếu như?",
    "」平行世界重跑時，也會在同一個時間重播這次干預。": "\" chạy lại thế giới song song, can thiệp này được phát lại cùng thời điểm.",
    "」平行世界重跑時，也會在同一個月份重播這次干預。": "\" chạy lại thế giới song song, can thiệp này được phát lại cùng tháng.",
    "」改寫。": "\" lúc này.",
    "」改寫它沒有發生。": "\" có thể viết lại để nó chưa từng xảy ra.",
    "」改寫（每一項都能點開追查原因）": "\" viết lại (mỗi mục có thể chạm để truy nguyên nhân)",
    "」改寫，看看世界會在什麼時候、因為什麼終結。": "\" viết lại, và xem thế giới kết thúc khi nào, vì sao.",
    "」與完整紀錄）。": "\" và toàn bộ hồ sơ).",
