    "：同時普及核能與火箭的國家是擁核國。": ": nước nào phổ biến cả điện hạt nhân lẫn tên lửa là cường quốc hạt nhân.",
    "：地球人口跌到高峰的 {0}% 以下就是文明崩潰，結局名稱取最近 40 年造成死亡最多的原因；超級智慧失控直接結束。": ": nếu dân số Trái Đất giảm xuống dưới {0}% mức đỉnh, nền văn minh sụp đổ, và kết cục được đặt theo nguyên nhân tử vong hàng đầu trong 40 năm gần nhất; siêu trí tuệ mất kiểm soát kết thúc mọi thứ ngay lập tức.",
    "：基因工程與合成生物學越普及、醫療越差、世界在打仗時，機率越高。": ": kỹ thuật di truyền và sinh học tổng hợp càng phổ biến, y tế càng kém và thế giới càng nhiều chiến tranh thì xác suất càng cao.",
