    "例如：如果沒有資本主義、沒有貨幣、人們不需要工作，而且人類不會變老。": "Ví dụ: nếu không có chủ nghĩa tư bản, không có tiền, con người không cần làm việc và không già đi thì sao?",
    "全球模式可以改變世界的根本規則：沒有資本主義、沒有貨幣、人們不需要工作、人類不會變老、地球沒有石油……也可以用一句話描述你想要的世界。": "Chế độ toàn cầu cho phép thay đổi quy tắc nền tảng của thế giới: không tư bản, không tiền, không cần làm việc, con người không già, Trái Đất không có dầu… hoặc mô tả thế giới bạn muốn trong một câu.",
